PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://data.briqhub.io/ref#>
SELECT ?sensor ?tsid WHERE {
  ?zone brick:hasName "Perimeter_ZN_3" ;
        brick:hasSubEntity ?sensor .
  ?sensor a brick:ElectricPowerSensor ;
          ref:hasTimeseriesId ?tsid .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://data.briqhub.io/ref#>
SELECT ?z ?zn WHERE {
  ?z a brick:Zone ; brick:hasName ?zn .
} LIMIT 30

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://data.briqhub.io/ref#>
SELECT ?s ?tsid WHERE {
  ?s a brick:ElectricPowerSensor ; ref:hasTimeseriesId ?tsid .
}

